{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "CJB 090, which shares the 2,3-dichlorophenylpiperazine motif and a basic aminoalkyl linker, entered the brain quickly and showed high brain penetration after i.v. dosing, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904, another 2,3-dichlorophenylpiperazine analogue with a basic butyl linker, also entered the brain quickly and demonstrated high brain penetration after i.v. dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In mice, (±)-1, containing the same dichlorophenylpiperazine and a polar hydroxypropyl amide linker, showed excellent brain penetrability with brain-to-plasma ratios of 6- to 20-fold after p.o. and i.v. dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "WAY-100635, a basic piperazine-containing 5-HT1A antagonist that is also an efflux-transporter substrate, achieved 5.0% maximal brain uptake in cynomolgus monkeys by PET, demonstrating that basic/efflux-substrate molecules can still have meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The closest analogue, a cyanopyridine-piperazine PET ligand, was an efflux substrate because cyclosporin A pretreatment increased its brain uptake; this indicates an efflux liability that may reduce, but does not by itself negate, meaningful CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite the physicochemical prior suggesting poor passive permeability and efflux liability, multiple close analogues with the same dichlorophenylpiperazine and basic amine scaffolds show high or adequate brain penetration after systemic dosing. The closest cyanopyridine-piperazine analogue is an efflux substrate, but this does not preclude meaningful CNS access, and direct brain-penetration evidence from related molecules dominates. Prediction: pass.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement for the exact query molecule.",
    "Unbound brain-to-plasma ratio and absolute brain concentrations are not available.",
    "Magnitude of efflux transporter impact on the query is unknown.",
    "Human CNS exposure data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

